<script>
import {onMount} from "svelte";
import {location} from "svelte-spa-router";
import {SCAN_EVENT,isScanActive,loadScanState} from "../lib/networkScan.js";
import {saveToolsOpen,toolsOpenForRoute} from "../lib/sidebarTools.js";
let activeScan=null,toolsOpen=true,lastLocation=null;
function refreshScan(){activeScan=loadScanState();}
function toggleTools(){toolsOpen=!toolsOpen;saveToolsOpen(toolsOpen);}
onMount(()=>{refreshScan();window.addEventListener(SCAN_EVENT,refreshScan);return()=>window.removeEventListener(SCAN_EVENT,refreshScan);});
$: scanRunning=isScanActive(activeScan);
$: if($location!==lastLocation){lastLocation=$location;toolsOpen=toolsOpenForRoute($location);}
const groups=[{title:"WORKSPACE",items:[["/","Overview","◈"],["/map","Maps","⌘"],["/docs","Documentation","▤"]]},{title:"INVENTORY",items:[["/inventory/hardware","Hosts","▦"],["/inventory/vms","VMs & runtimes","◇"],["/inventory/apps","Applications","▧"],["/groups","Container groups","▥"],["/inventory/networks","Networks","◎"],["/inventory/storage","Storage & shares","▱"],["/inventory/misc","Other devices","⋯"]]}];
const tools=[["/network-discovery","Network discovery","◉"],["/reconciliation","Reconciliation","⇄"]];
const preferences={title:"PREFERENCES",items:[["/settings","Settings","⚙"]]};
const active=p=>p==="/"?$location==="/":$location.startsWith(p);
</script>
<nav class="sidebar" aria-label="Main navigation">{#each groups as group}<div class="nav-group"><p>{group.title}</p>{#each group.items as [path,label,icon]}<a href={`#${path}`} class:active={active(path)} aria-current={active(path)?"page":undefined}><span aria-hidden="true">{icon}</span>{label}</a>{/each}</div>{/each}<div class="nav-group tools-group"><button type="button" class="tools-toggle" class:active={tools.some(([path])=>active(path))} aria-expanded={toolsOpen} aria-controls="sidebar-tools" on:click={toggleTools}><span>TOOLS</span><span class="tools-chevron" aria-hidden="true">{toolsOpen?"▾":"▸"}</span></button><div id="sidebar-tools" class="tools-items" hidden={!toolsOpen}>{#each tools as [path,label,icon]}<a href={`#${path}`} class:active={active(path)} aria-current={active(path)?"page":undefined}><span aria-hidden="true">{icon}</span>{label}</a>{/each}</div></div><div class="nav-group"><p>{preferences.title}</p>{#each preferences.items as [path,label,icon]}<a href={`#${path}`} class:active={active(path)} aria-current={active(path)?"page":undefined}><span aria-hidden="true">{icon}</span>{label}</a>{/each}</div>{#if scanRunning}<a class="scan-indicator" href="#/network-discovery" title="Network scan in progress"><span aria-hidden="true">◉</span>Scan running{#if activeScan?.target}<small>{activeScan.target}</small>{/if}</a>{/if}<div class="sidebar-note">A reference for your lab.<br/>Built to be returned to.</div></nav>
<style>.sidebar{width:220px;min-width:220px;display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;background:var(--pico-card-background-color);border-right:1px solid var(--pico-muted-border-color);padding:1.1rem .7rem;gap:1.4rem;position:sticky;top:0;height:calc(100vh - 76px);overflow-y:auto}.nav-group{display:flex;flex-direction:column;gap:.25rem}.nav-group p,.tools-toggle{font-size:.6rem;letter-spacing:.13em;font-weight:700;color:var(--pico-muted-color);padding:.2rem .7rem;margin:0 0 .4rem}.tools-group{border-top:1px solid var(--pico-muted-border-color);padding-top:1rem}.tools-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;background:none;box-shadow:none;border:0;border-radius:6px;cursor:pointer;text-align:left;text-transform:uppercase}.tools-toggle:hover{color:var(--pico-color);background:var(--hlh-tint)}.tools-toggle.active{color:var(--pico-primary)}.tools-toggle:focus-visible{outline:2px solid var(--pico-primary);outline-offset:2px}.tools-chevron{font-size:.7rem;letter-spacing:0}.tools-items{display:flex;flex-direction:column;gap:.25rem}.tools-items[hidden]{display:none}.sidebar a{display:flex;gap:.65rem;align-items:center;padding:.65rem .7rem;margin:0;border-radius:8px;font-size:.8rem;text-decoration:none;color:var(--pico-color)}.sidebar a span{font-size:1.05rem;width:1.2rem;text-align:center;color:var(--pico-muted-color)}.sidebar a:hover{background:var(--hlh-tint)}.sidebar a.active{background:var(--hlh-tint);color:var(--pico-primary);font-weight:650}.sidebar a.active span{color:var(--pico-primary)}.scan-indicator{border:1px solid var(--pico-primary)!important;color:var(--pico-primary)!important;background:var(--hlh-tint);flex-wrap:wrap}.scan-indicator small{width:100%;font-size:.65rem;color:var(--pico-muted-color);overflow-wrap:anywhere}.sidebar-note{font-size:.65rem;color:var(--pico-muted-color);padding:1rem .7rem;margin-top:auto}@media(max-width:760px){.sidebar{width:100%;min-width:0;height:auto;position:static;flex-direction:row;overflow-x:auto;padding:.5rem;border-right:0;border-bottom:1px solid var(--pico-muted-border-color);gap:.5rem}.nav-group{flex-direction:row;gap:.2rem}.nav-group p,.sidebar-note{display:none}.tools-group{border-top:0;padding-top:0}.tools-toggle{width:auto;margin:0;padding:.45rem .6rem;font-size:.6rem;border:1px solid var(--pico-muted-border-color)}.tools-items{flex-direction:row;gap:.2rem}.sidebar a{white-space:nowrap;font-size:.7rem;padding:.45rem .6rem}.sidebar a span{display:none}}</style>
